```sparql
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmName ?director ?directorName ?birthDate
WHERE {
  VALUES ?film { dbr:Folly_to_Be_Wise dbr:The_Jerk }

  # film name (prefer dbp:name, fallback to rdfs:label)
  OPTIONAL { ?film dbp:name ?filmName . }
  OPTIONAL { ?film rdfs:label ?filmName FILTER (lang(?filmName) = "en") }

  # director (prefer dbp:director, fallback to dbo:director)
  { ?film dbp:director ?director . }
  UNION
  { ?film dbo:director ?director . }

  # director name (prefer dbp:name, fallback to rdfs:label)
  OPTIONAL { ?director dbp:name ?directorName . }
  OPTIONAL { ?director rdfs:label ?directorName FILTER (lang(?directorName) = "en") }

  # director birth date (prefer dbp:birthDate, fallback to dbo:birthDate)
  { ?director dbp:birthDate ?birthDate . }
  UNION
  { ?director dbo:birthDate ?birthDate . }
}
LIMIT 100
